insert into public.levels (id, number, title, subtitle) values
  ('5205f538-ab53-5503-b56a-f8e7749388b5', 1, 'المستوى الأول', 'المستوى الأول يضم مسارين متوازيين: تمهيد طلب العلم الشرعي لبناء الأساس المعرفي، وسلاسل التزكية لإصلاح القلب وتهذيب النفس. كلاهما ضروري للسير في طريق الدين على بصيرة.'),
  ('d6b15e73-1251-548e-b63b-875854645886', 2, 'المستوى الثاني', 'المستوى الثاني يضم مسارَين: المرحلة الثالثة للتزكية بسلاسلها المتواصلة، وتمهيد العبادة لتعميق صلتك بالله.'),
  ('de554c38-b151-55c4-8a05-1ee8a74e9cbc', 3, 'المستوى الثالث', 'المستوى الثالث يضم مسارَين: تمهيد التزكية لبناء الأساس التربوي الداخلي، وتمهيد الدعوة والإصلاح لتأسيس الوعي الدعوي ومنهج المصلح.'),
  ('f0cd4b05-25be-578f-a0c0-e709c473a3c1', 4, 'المستوى الرابع', 'التمهيد العام — ثلاثة مسارات تُكمل البناء: دروس تأسيسية في فهم الإسلام، وخمسة كتب مرجعية، وثماني قوائم تشغيل تُغطي الثقافة المتكاملة والإشكاليات الفكرية وفقه التصورات ومنهاج النبوة.');
insert into public.tracks (id, level_id, title, description, accent, intro_audio_url, sort) values
  ('9aff764f-8134-53db-ba7c-42e0c1054731', '5205f538-ab53-5503-b56a-f8e7749388b5', 'تمهيد طلب العلم', 'تأسيسك في طريق العلم الشرعي: من فهم حقيقة العلم وفضله، إلى بناء شخصيتك كطالب علم، مرورًا بمداخل العلوم الشرعية المختلفة.', 'green', 'https://drive.google.com/file/d/1V06X2mXh_6CO7_FU61coAZdUYSP07Dqb/view?usp=drivesdk', 0),
  ('03f8af2a-fef0-5323-befb-9de08aac2aac', '5205f538-ab53-5503-b56a-f8e7749388b5', 'سلاسل التزكية', 'رحلة إصلاح القلب وتهذيب النفس — من التوبة ومحاسبة النفس إلى الترقي في مقامات العبودية والتقرب إلى الله.', 'gold', 'https://drive.google.com/file/d/1Oq6fm13_aLGexk9cw0k16IoSWECY2hUn/view?usp=drivesdk', 1),
  ('70038f80-680f-57d0-975f-e045f0d705cd', 'd6b15e73-1251-548e-b63b-875854645886', 'التزكية — المرحلة الثالثة', 'المرحلة الثالثة والأعمق في تزكية النفس — تشمل السيرة النبوية كاملة، وأحداث نهاية العالم، والدار الآخرة. تُكمَل السلاسل واحدة تلو الأخرى.', 'gold', 'https://drive.google.com/file/d/1w_z8VOzcxWnQi9fetX_wBiINYLtnuSMN/view?usp=drivesdk', 0),
  ('3f80696d-9ed3-540a-9395-e6f7a45ea290', 'd6b15e73-1251-548e-b63b-875854645886', 'تمهيد العبادة', 'أربعة كتب تؤسسك في مفهوم العبودية الحقيقية وتعمّق صلتك بالله — من فهم حقيقة التعبد إلى السير في طريق المتعبدين.', 'green', 'https://drive.google.com/file/d/100AwKqL70ECPEeOl6T9frhU9Ef5EiZ_f/view?usp=drivesdk', 1),
  ('6d7a338c-863c-5a7e-b49f-fca39e71f973', 'de554c38-b151-55c4-8a05-1ee8a74e9cbc', 'تمهيد التزكية', 'خمسة مراجع تؤسس البنية التربوية الداخلية — من مقدمات التزكية وتزكية العقل والجسد والقلب، إلى دستور الملتزم وأسس الوعي التربوي والوصية الصغرى والخلاصة في التربية.', 'gold', 'https://drive.google.com/file/d/1p401qD_gmcTOJT6OmTTrPzolXQPDLRyt/view?usp=drivesdk', 0),
  ('695bd1db-fd52-5b4b-ba61-49660ed21e40', 'de554c38-b151-55c4-8a05-1ee8a74e9cbc', 'تمهيد الدعوة والإصلاح', 'بناء الوعي الدعوي ومنهج المصلح — ثلاثة كتب في أصول الدعوة تضع المعالم الكبرى للعمل الدعوي والإصلاحي.', 'blue', 'https://drive.google.com/file/d/1TIbJyZyRpu4hgICWAHpRpSQ6_jGRICyC/view?usp=drivesdk', 1),
  ('4248f3df-0918-537f-8e98-9893177e1225', 'f0cd4b05-25be-578f-a0c0-e709c473a3c1', 'الدروس', 'دروس تأسيسية ومحورية في فهم الإسلام والاهتداء بالقرآن — من مقدمات فهم النصوص الشرعية إلى معالم الهداية بالقرآن.', 'green', 'https://drive.google.com/file/d/1ZBpHj4ORHxnHtX4TpOOlEmzrVWUJZ2cS/view?usp=drivesdk', 0),
  ('5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', 'f0cd4b05-25be-578f-a0c0-e709c473a3c1', 'قوائم التشغيل', 'ثماني قوائم تشغيل شاملة — الثقافة المتكاملة، والدروس المحورية، وسلسلة الإشكاليات، وفقه التصورات، والعقلية الإدارية، ودفتر وعي، ومنهاج النبوة.', 'blue', 'https://drive.google.com/file/d/1kZzjoE6dOlIEY5y4FbjduiFV8M1qykFN/view?usp=drivesdk', 1),
  ('1d42460f-955b-55dd-8844-6e60ddda539a', 'f0cd4b05-25be-578f-a0c0-e709c473a3c1', 'الكتب', 'خمسة كتب مرجعية تُكمل التأسيس العام — من مدخل فهم الإسلام وشخصية المسلم إلى مفاهيم أهل السنة والأسئلة الأربعة بجزأيها.', 'gold', 'https://drive.google.com/file/d/1rM0IEIir0sS_sQYetYVZgae3P6aVCLQo/view?usp=drivesdk', 2);
insert into public.sections (id, track_id, parent_id, title, description, intro_audio_url, sort) values
  ('76e6bbec-4448-571f-ac6a-1332d3b50e2b', '9aff764f-8134-53db-ba7c-42e0c1054731', null, 'حقيبة مفاتيح الطلب', 'سلسلة تأسيسية تضع بين يديك مفاتيح طلب العلم الشرعي — من فهم حقيقة العلم وفضله، إلى بناء شخصية طالب العلم والتعرف على العوائق وطرق تجاوزها.', 'https://drive.google.com/file/d/1DtdA2MQ1OBOD62AusWeo1ndu03IDiX1X/view?usp=drivesdk', 0),
  ('3abd76ac-6183-560e-bbf3-7d102e304aea', '9aff764f-8134-53db-ba7c-42e0c1054731', null, 'سلسلة مهارات التعلم', 'سلسلة تُعنى بتطوير مهارات التعلم الفعّال — من أساليب الحفظ والمراجعة إلى تنظيم الوقت وإدارة المعرفة.', 'https://drive.google.com/file/d/1736UWRkrHKdDeV9lAUKgtGqzEtzPadm1/view?usp=drivesdk', 1),
  ('5f93da4f-fe2e-50de-84c7-4bdb263b9010', '9aff764f-8134-53db-ba7c-42e0c1054731', null, 'مداخل العلوم الشرعية', 'مقدمات تعريفية بالعلوم الشرعية المختلفة — تعطيك تصورًا عامًا عن كل علم قبل الشروع في دراسته تفصيلًا.', 'https://drive.google.com/file/d/1KwNpqitwIqhXdR7rKmHyucHPs6cHdDwM/view?usp=drivesdk', 2),
  ('957776bd-8f1b-52ea-b571-cba86d9b9af2', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل العقيدة', null, null, 0),
  ('bef12eac-1c54-5236-844c-92ef792f4b2c', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل اللغة العربية', null, null, 1),
  ('044c14ed-aedc-5b54-807c-c03f00d8005f', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل الفقه', null, null, 2),
  ('e529adf4-8489-5ff6-90af-4c727b195d06', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل أصول الفقه', null, null, 3),
  ('f17b747c-d002-5990-a63c-716da63d6894', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل علوم القرآن', null, null, 4),
  ('d41a03a1-9266-5863-b8a7-062884d28fc1', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل التفسير', null, null, 5),
  ('fd3a8994-22c4-5fb4-932c-dd8b0a8e585d', '9aff764f-8134-53db-ba7c-42e0c1054731', '5f93da4f-fe2e-50de-84c7-4bdb263b9010', 'مدخل علوم السيرة', null, null, 6),
  ('1daf057c-a046-5bf5-96b1-2d6dd2ced29d', '9aff764f-8134-53db-ba7c-42e0c1054731', null, 'كتاب معارج العلوم', 'كتاب مرافق يضع بين يديك خريطة واضحة لفهم العلوم الشرعية ومراتبها.', 'https://drive.google.com/file/d/15QG0PzauLheqNm11nZ3vOySRY4lvwIHO/view?usp=drivesdk', 3),
  ('8988b81a-d4fb-50ed-a278-e41f3357721b', '03f8af2a-fef0-5323-befb-9de08aac2aac', null, 'المرحلة الأولى — تأسيس وإصلاح', 'مرحلة تأسيسية في تزكية النفس — تبدأ بمعرفة الله عز وجل، ثم معرفة النفس والقلب وآفاته، ثم معرفة الطريق إلى الله وأساسياته ومعوقاته.', 'https://drive.google.com/file/d/162ZktJBq6pmR00nmR_mRPHN6_HM4htpz/view?usp=drivesdk', 0),
  ('3a66f902-d70d-57a7-bc08-311f929f9777', '03f8af2a-fef0-5323-befb-9de08aac2aac', '8988b81a-d4fb-50ed-a278-e41f3357721b', 'معرفة الله', null, null, 0),
  ('a5525892-760f-5fef-8bc9-b757a8639a2d', '03f8af2a-fef0-5323-befb-9de08aac2aac', '8988b81a-d4fb-50ed-a278-e41f3357721b', 'معرفة النفس والقلب — المدرسة الإيمانية', null, null, 1),
  ('f7d1f429-f826-5615-870f-e563297e59c5', '03f8af2a-fef0-5323-befb-9de08aac2aac', '8988b81a-d4fb-50ed-a278-e41f3357721b', 'معرفة النفس والقلب — مع نفسي', null, null, 2),
  ('eee4eb6d-d11f-50f4-99c5-255c2a63bf1d', '03f8af2a-fef0-5323-befb-9de08aac2aac', '8988b81a-d4fb-50ed-a278-e41f3357721b', 'معرفة الطريق — أساسيات الطريق إلى الله', null, null, 3),
  ('710e89cf-f976-5a42-8d49-67c2af27b035', '03f8af2a-fef0-5323-befb-9de08aac2aac', '8988b81a-d4fb-50ed-a278-e41f3357721b', 'معرفة الطريق — معوقات الطريق إلى الله', null, null, 4),
  ('d4db5bce-d798-547c-8db4-d146ce5d12c2', '03f8af2a-fef0-5323-befb-9de08aac2aac', null, 'المرحلة الثانية — بناء وترقّي', 'مرحلة البناء والترقي في مقامات العبودية — بعد التأسيس والإصلاح، تبدأ بالتحلي بالأخلاق الفاضلة، وتعميق معرفة النفس والقلب، والسير في طريق التقرب إلى الله.', 'https://drive.google.com/file/d/1_yKD-Xmf_ZWT-gAYMC8tcofRC-ovNJum/view?usp=drivesdk', 1),
  ('4a5fa3dd-9d77-547b-865b-c4081ba366b4', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'الأخلاق — السلسلة الأولى', null, null, 0),
  ('12f7648f-9e05-5684-a413-2023cdc2c249', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'الأخلاق — السلسلة الثانية', null, null, 1),
  ('04b51fd0-906e-57c9-ab9f-088881ba2eb4', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'معرفة النفس والقلب — سلسلة إصلاح القلوب', null, null, 2),
  ('8ac607ac-1302-5eb9-8767-4f931d7a6359', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'معرفة الطريق — إصلاح العبادات', null, null, 3),
  ('06dba47e-b277-5c2a-a658-42351ab13b72', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'معرفة الطريق — كيف نتدبر القرآن', null, null, 4),
  ('b8c42bc0-23d5-5fc8-8410-e8102cb8da2c', '03f8af2a-fef0-5323-befb-9de08aac2aac', 'd4db5bce-d798-547c-8db4-d146ce5d12c2', 'معرفة الطريق — عن القرآن', null, null, 5),
  ('2845d498-572b-56c9-b0f8-65fa1ab7336d', '70038f80-680f-57d0-975f-e045f0d705cd', null, 'السيرة النبوية', '51 درسًا تأخذك في رحلة كاملة مع حياة النبي ﷺ من البداية الإبراهيمية حتى الوفاة، مع أعمق الدروس والفوائد التربوية.', null, 0),
  ('f4480fef-c4ed-5b7e-9d10-f5cfdacd8a29', '70038f80-680f-57d0-975f-e045f0d705cd', null, 'أحداث نهاية العالم', '28 درسًا في رحلة مفصّلة مع علامات الساعة والأحداث العظيمة في آخر الزمان.', null, 1),
  ('092ccf11-7a93-56ef-86fb-6124537a6590', '70038f80-680f-57d0-975f-e045f0d705cd', null, 'الدار الآخرة', '12 درسًا في رحلة مؤثرة من لحظة الموت حتى الجنة أو النار — تُحيي القلب وتُجدد الصلة بالآخرة.', null, 2),
  ('c0e2a31c-cb1e-5cc4-b9fc-ace05c9a7559', '70038f80-680f-57d0-975f-e045f0d705cd', null, 'وقفات تربوية جامعة', 'خاتمة المرحلة الثالثة — وقفات تربوية جامعة تُلملم خيوط ما سبق، وتضع المتربي على أعتاب الانطلاق العملي بهدف واضح وقرارٍ ثابت.', null, 3),
  ('2510aba5-e301-5a50-88a2-5f5f7c625b77', '3f80696d-9ed3-540a-9395-e6f7a45ea290', null, 'كتب تمهيد العبادة', 'أربعة كتب تُقرأ بالترتيب — كل كتاب يُعمّق ما قبله ويُمهّد لما بعده في فهم حقيقة العبودية.', null, 0),
  ('7232e3d2-815d-5c15-a706-9e538e6f9d3e', '6d7a338c-863c-5a7e-b49f-fca39e71f973', null, 'مقدمات في التزكية', 'أربعة كتب تُؤسّس فهمك لمعنى التزكية وأبعادها — تزكية العقل والجسد والقلب. اقرأها بالترتيب.', null, 0),
  ('8f4fb7d8-a1b1-5cd0-9ac5-454d66b757c1', '6d7a338c-863c-5a7e-b49f-fca39e71f973', null, 'تأسيس الوعي التربوي', 'كتاب يُبني الأساس النظري للعملية التربوية — فهم المنطلقات والمرجعيات التي تُحكم أي مسار تربوي صحيح.', null, 1),
  ('fe96d22d-f9e4-5398-af2d-ff16324dc920', '6d7a338c-863c-5a7e-b49f-fca39e71f973', null, 'دستور الملتزم الجديد', 'كتاب يضع الأُطر العملية لحياة الملتزم الجديد — المنهج اليومي والأولويات والسلوكيات التي تنظم الالتزام.', null, 2),
  ('9e552550-03f3-5bba-a736-e2490faf6639', '6d7a338c-863c-5a7e-b49f-fca39e71f973', null, 'تفريغ شرح الوصية الصغرى', 'شرح الوصية الصغرى لابن تيمية — وصايا جامعة في التربية والسلوك والعلاقة بالله والناس.', null, 3),
  ('ad1cc35d-2534-5c32-af47-bd0924c9bed4', '6d7a338c-863c-5a7e-b49f-fca39e71f973', null, 'الخلاصة في التربية', 'كتاب يجمع خلاصة المنهج التربوي — مرجع جامع للمراجعة والتثبيت في نهاية مسار تمهيد التزكية.', null, 4),
  ('250c7e12-6876-54ed-9e0a-795f3cd94ee7', '695bd1db-fd52-5b4b-ba61-49660ed21e40', null, 'تأسيس الوعي الدعوي', 'كتاب يُؤسّس الفهم الصحيح لمعنى الدعوة وأهدافها ومنطلقاتها — لا بد من قراءته قبل الشروع في أي عمل دعوي.', null, 0),
  ('64a46d64-642f-59c5-8429-0659b68950ec', '695bd1db-fd52-5b4b-ba61-49660ed21e40', null, 'علم الدعوة إلى الله تعالى', 'كتاب يُعرّف بعلم الدعوة كفنّ وعلم له أصوله ومسائله — منهج متكامل في فهم الدعوة من منظور علمي.', null, 1),
  ('18553ae0-2880-520f-bc04-249718ac46e1', '695bd1db-fd52-5b4b-ba61-49660ed21e40', null, 'معالم في أصول الدعوة', 'كتاب يضع المعالم الكبرى في أصول الدعوة ومرجعياتها — مرجع جامع لمن يريد ضبط منهجه الدعوي.', null, 2),
  ('0aec2b32-48f3-5e28-bbd8-8842e345d3e4', '4248f3df-0918-537f-8e98-9893177e1225', null, 'مقدمات في فهم الإسلام', 'دروس تُؤسّس المنهج الصحيح في فهم الإسلام والاهتداء بالقرآن — ابدأ بها قبل الدخول في قوائم التشغيل والكتب.', null, 0),
  ('e742ffd7-0d66-5f7d-82a4-48994960d5a2', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'الثقافة المتكاملة وفيديوهات أخرى', 'خمس ندوات تُمهّد لفهم الثقافة الإسلامية المتكاملة، يتبعها مجموعة من الفيديوهات في الانضباط الذاتي والعلاقات والصحة النفسية ومهارات العبادة.', null, 0),
  ('b2395d1b-84cd-5d06-beda-483ae10fced3', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'دروس محورية', 'سبعة دروس تدور حول محاور تربوية جوهرية — الإنسان في القرآن، وفقه الاختيار، ومعارج الإيمان، وفقه الحياة.', null, 1),
  ('189c5bf7-2f02-5744-a7f5-2b8067a6c21f', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'سلسلة إشكاليات', 'ثلاثة عشر درسًا تُعالج الإشكاليات الفكرية والتربوية الكبرى — من البناء المعرفي والتدين المعاصر إلى اليأس والإحباط وظاهرة سقوط الكوادر.', null, 2),
  ('7e2b990f-667f-59fc-a38d-ae7dc6e58fcd', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'إحياء منهاج النبوة', 'سبعة دروس تُحيي منهاج النبوة في التلقي والتربية والإصلاح — مسار متكامل يُعيد ربط المسلم بالمنهج النبوي الأصيل.', null, 3),
  ('ea92cbe8-7e90-527d-8f64-3ad6a81eb0b2', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'شرح المنهاج من ميراث النبوة', 'سبعة وثلاثون درسًا تشرح المنهاج من ميراث النبوة تفصيلاً — من مرجعية الوحي إلى السياسة والحكم، مرورًا بالتزكية والعلم والإصلاح والثبات.', null, 4),
  ('2bb84e51-1bc2-50d3-b17c-acfc52e32303', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'العقلية الإدارية', 'درسان يؤسّسان العقلية الإدارية للمسلم العامل — ضبط الجهد وتنظيم العمل وترتيب الأولويات في الميدان الدعوي والإصلاحي.', null, 5),
  ('4540e6f0-7171-56bd-9707-8d00f85d20a9', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'دفتر وعي', 'ثمانية دروس في بناء الشخصية والتقوى — من فقه النعمة وقواعد ابن تيمية في بناء الشخصية إلى التقوى بوصفها ضمير المسلم.', null, 6),
  ('440e185a-692c-5554-8c65-32f2fe7639ea', '5ff4341b-9a2c-5e01-94d7-3a6daa78cd18', null, 'فقه التصورات', 'ستة دروس تُصحّح التصورات الكبرى وتضبط طريقة نظر المسلم إلى الدين والنفس والواقع.', null, 7),
  ('9ee79009-6624-5440-b735-992faf7fa39a', '1d42460f-955b-55dd-8844-6e60ddda539a', null, 'مدخل لفهم الإسلام', 'كتاب يُرسّخ المدخل الصحيح لفهم الإسلام دينًا وحضارةً — أساس لا غنى عنه قبل الدخول في التفاصيل.', null, 0),
  ('c7d87a3a-2b4d-5c71-bce7-00645365f74f', '1d42460f-955b-55dd-8844-6e60ddda539a', null, 'المختصر في خلق المسلم', 'مختصر جامع يُبيّن ملامح شخصية المسلم في أخلاقه وسلوكه وتعامله مع ربه ونفسه والناس.', null, 1),
  ('49ea8003-6608-5b54-86ae-371a7ed023ec', '1d42460f-955b-55dd-8844-6e60ddda539a', null, 'شخصية المسلم', 'كتاب يرسم صورة متكاملة لشخصية المسلم — في علاقته بالله والناس والمجتمع، مع التأصيل الشرعي لكل جانب.', null, 2),
  ('7728aaa1-ff8a-5b95-9d52-893389efda2a', '1d42460f-955b-55dd-8844-6e60ddda539a', null, 'خلاصة مفاهيم أهل السنة والجماعة', 'خلاصة منهجية للمفاهيم العقدية والمنهجية لأهل السنة — مرجع يضبط التصور ويُصحح المفاهيم الملتبسة.', null, 3),
  ('9af683d0-1004-54ba-bb49-73e9407ce9a5', '1d42460f-955b-55dd-8844-6e60ddda539a', null, 'الأسئلة الأربعة', 'كتاب بجزأين يُجيب على الأسئلة الأربعة الجوهرية التي يواجهها كل مسلم في رحلته — اقرأ الجزأين بالترتيب.', null, 4);
